import json, hashlib, sys

def sha(p):
    return hashlib.sha256(open(p, 'rb').read()).hexdigest()

def walk(o, out):
    if isinstance(o, dict):
        if 'path' in o and 'sha256' in o and isinstance(o['path'], str) and isinstance(o['sha256'], str):
            out.append(o)
        for v in o.values():
            walk(v, out)
    elif isinstance(o, list):
        for v in o:
            walk(v, out)

apply = len(sys.argv) > 1 and sys.argv[1] == 'apply'
pp = 'benchmark/writing/input-pins.json'
d = json.load(open(pp))
m = d['protected_inputs_sha256']
bad = {k: sha(k) for k, v in m.items() if sha(k) != v}
print('input-pins entries', len(m), 'mismatched', sorted(bad))
pr = 'benchmark/preparation.json'
d2 = json.load(open(pr))
ents = []
walk(d2, ents)
bad2 = [e for e in ents if sha(e['path']) != e['sha256']]
print('preparation entries', len(ents), 'mismatched', [e['path'] for e in bad2])
if apply:
    txt = open(pp).read()
    for k, new in bad.items():
        txt = txt.replace(m[k], new)
    open(pp, 'w').write(txt)
    txt = open(pr).read()
    for e in bad2:
        txt = txt.replace(e['sha256'], sha(e['path']))
    open(pr, 'w').write(txt)
    print('applied')

